async def act(page):
    """
    From the current Order View, open the Shipping Address edit page and update the address to:
      654 Elm Drive, Apartment 12
      Miami, FL, 33101

    Uses a relative goto to the shipping address edit URL shown in the current accessibility tree
    (/index.php/admin/sales_order/address/address_id/749/) and fills fields via accessibility-role selectors.
    """
    import asyncio

    # Knowledge base functions: none are available for this task, so none are used.

    # Navigate directly to the shipping address edit page (address_id/749 from the accessibility tree)
    await page.goto('/index.php/admin/sales_order/address/address_id/749/')
    await page.wait_for_load_state('networkidle')
    # give dynamic content a moment to render
    await asyncio.sleep(1)

    # STREET fields (Magento often exposes multiple street textboxes)
    street_locator = page.get_by_role('textbox', name='street')
    if await street_locator.count() > 0:
        # Primary street line
        await street_locator.nth(0).fill('654 Elm Drive')
        # Secondary line for apartment if present
        if await street_locator.count() > 1:
            await street_locator.nth(1).fill('Apartment 12')
        else:
            # If only one street input exists, append apartment information
            try:
                current = await street_locator.nth(0).input_value()
            except Exception:
                current = ''
            if current and 'Apartment' not in current:
                new_val = current.rstrip() + ', Apartment 12'
            else:
                new_val = '654 Elm Drive, Apartment 12'
            await street_locator.nth(0).fill(new_val)
    else:
        # Fallback: try a generic address textbox
        addr_locator = page.get_by_role('textbox', name='address')
        if await addr_locator.count() > 0:
            await addr_locator.first.fill('654 Elm Drive, Apartment 12')

    # CITY
    city_locator = page.get_by_role('textbox', name='city')
    if await city_locator.count() > 0:
        await city_locator.first.fill('Miami')

    # REGION / STATE (prefer combobox selection)
    region_combobox = page.get_by_role('combobox', name='region')
    region_combobox_alt = page.get_by_role('combobox', name='state')
    region_combobox_alt2 = page.get_by_role('combobox', name='state/province')
    if await region_combobox.count() > 0:
        try:
            await region_combobox.first.select_option(label='Florida')
        except Exception:
            try:
                await region_combobox.first.select_option(value='FL')
            except Exception:
                pass
    elif await region_combobox_alt.count() > 0:
        try:
            await region_combobox_alt.first.select_option(label='Florida')
        except Exception:
            try:
                await region_combobox_alt.first.select_option(value='FL')
            except Exception:
                pass
    elif await region_combobox_alt2.count() > 0:
        try:
            await region_combobox_alt2.first.select_option(label='Florida')
        except Exception:
            try:
                await region_combobox_alt2.first.select_option(value='FL')
            except Exception:
                pass
    else:
        # Fallback to textbox inputs named region/state
        region_text = page.get_by_role('textbox', name='region')
        if await region_text.count() > 0:
            await region_text.first.fill('FL')
        else:
            region_text2 = page.get_by_role('textbox', name='state')
            if await region_text2.count() > 0:
                await region_text2.first.fill('FL')
            else:
                region_text3 = page.get_by_role('textbox', name='state/province')
                if await region_text3.count() > 0:
                    await region_text3.first.fill('FL')

    # POSTCODE / ZIP
    postcode_loc = None
    for name_variant in ('postcode', 'postal', 'zip', 'zip code', 'zip/postal'):
        candidate = page.get_by_role('textbox', name=name_variant)
        if await candidate.count() > 0:
            postcode_loc = candidate.first
            break
    if postcode_loc:
        await postcode_loc.fill('33101')

    # TELEPHONE: do not overwrite if already present; fill if empty
    tel_candidates = page.get_by_role('textbox', name='telephone')
    if await tel_candidates.count() > 0:
        tel = tel_candidates.first
        try:
            current_tel = await tel.input_value()
        except Exception:
            current_tel = ''
        if not current_tel:
            await tel.fill('(305) 555-0100')

    # SAVE the updated address - try likely save labels
    for label in ('Save Address', 'Save'):
        btn = page.get_by_role('button', name=label)
        if await btn.count() > 0:
            await btn.first.click()
            await page.wait_for_load_state('networkidle')
            return

    # Fallback: click any button whose aria-label or title contains 'save'
    all_buttons = page.get_by_role('button')
    total = await all_buttons.count()
    for i in range(total):
        b = all_buttons.nth(i)
        try:
            aria = await b.get_attribute('aria-label') or ''
            title = await b.get_attribute('title') or ''
            if (aria and 'save' in aria.lower()) or (title and 'save' in title.lower()):
                await b.click()
                await page.wait_for_load_state('networkidle')
                return
        except Exception:
            try:
                await b.click()
                await page.wait_for_load_state('networkidle')
                return
            except Exception:
                continue

    # If we cannot find a save control, raise an explicit error
    raise RuntimeError('Could not find a Save button to persist the updated address.')

